SELECT PD.DEPARTMENT_NAME AS "department.parentDepartment.departmentName" ,U.USER_ID AS userId ,D.DEPARTMENT_NAME AS "department.departmentName" ,U.NAME AS name ,U.PROFILE_IMG_PATH AS profileImgPath ,P.POSITION_NAME AS "position.positionName" FROM GROUVY_USERS U, GROUVY_DEPARTMENTS D, GROUVY_POSITIONS P , GROUVY_DEPARTMENTS PD WHERE U.DEPARTMENT_ID(+) = D.DEPARTMENT_ID AND U.POSITION_NO = P.POSITION_NO(+) AND PD.DEPARTMENT_ID(+) = D.PARENT_DEPARTMENT_ID
AND D.PARENT_DEPARTMENT_ID = #{deptId}
AND D.DEPARTMENT_ID = #{deptId}
START WITH D.PARENT_DEPARTMENT_ID IS NULL CONNECT BY PRIOR D.DEPARTMENT_ID = D.PARENT_DEPARTMENT_ID ORDER SIBLINGS BY D.DEPARTMENT_ID , P.POSITION_NO

SELECT R.ROOM_ID AS roomId ,R.ROOM_NAME AS roomName ,R.IS_GROUP AS isGroup FROM GROUVY_CHAT_ROOMS R, GROUVY_CHAT_ROOM_USERS U WHERE R.ROOM_ID = U.ROOM_ID
AND U.IS_ACTIVE = 'Y'
GROUP BY R.ROOM_ID, R.ROOM_NAME, R.IS_GROUP HAVING COUNT(*) = #{listSize} AND COUNT(DISTINCT U.USER_ID) = #{listSize} AND SUM(CASE WHEN U.USER_ID IN
#{userId}
THEN 1 ELSE 0 END) = #{listSize}

mapper.update:
UPDATE GROUVY_CHAT_ROOM_USERS
SET
IS_ACTIVE = #{isActive}

    ,LEFT_DATE = #{leftDate}


    ,JOIN_DATE = #{joinDate}

WHERE
USER_ID = #{userId}
AND ROOM_ID = #{roomId}
